# Windows x64; PowerShell 5.1 or later. Zstandard 1.5.7 is embedded below.
# Zstandard license: BSD-3-Clause. Full notice is included at the end of this file.
[CmdletBinding()]
param(
    [string]$UserDataDirectory = (Join-Path $env:LOCALAPPDATA 'Google\Chrome\User Data'),
    [switch]$Check,
    [string]$RestoreBackup,
    [string]$BackupDirectory = ''
)
$ErrorActionPreference = 'Stop'
if (-not $BackupDirectory) { $BackupDirectory = Join-Path $PSScriptRoot 'Backups' }
$taskRuntimeDirectory = $null
$taskBackupPath = $null
$taskStreams = @()
$taskEntries = @()
$taskWroteFiles = $false
$taskFinished = $false
function Get-TaskHash([byte[]]$Bytes) {
    $taskHasher = [Security.Cryptography.SHA256]::Create()
    try { return ([BitConverter]::ToString($taskHasher.ComputeHash($Bytes))).Replace('-', '').ToLowerInvariant() }
    finally { $taskHasher.Dispose() }
}
function Read-TaskStream([IO.FileStream]$Stream) {
    if ($Stream.Length -gt 52428800) { throw 'File exceeds the 50 MiB limit.' }
    $taskBuffer = New-Object byte[] ([int]$Stream.Length)
    $Stream.Position = 0
    $taskOffset = 0
    while ($taskOffset -lt $taskBuffer.Length) {
        $taskRead = $Stream.Read($taskBuffer, $taskOffset, $taskBuffer.Length - $taskOffset)
        if ($taskRead -eq 0) { throw 'Unexpected end of file.' }
        $taskOffset += $taskRead
    }
    return ,$taskBuffer
}
function Write-TaskStream([IO.FileStream]$Stream, [byte[]]$Bytes) {
    $Stream.Position = 0
    $Stream.Write($Bytes, 0, $Bytes.Length)
    $Stream.SetLength($Bytes.Length)
    $Stream.Flush($true)
}
function Assert-TaskChromeClosed {
    if (@(Get-Process -Name chrome -ErrorAction SilentlyContinue).Count -gt 0) {
        throw 'Chrome is running. Close all Chrome windows and background chrome.exe processes, then run again. The script does not force-close Chrome.'
    }
}
try {
    if (-not [Environment]::Is64BitProcess) { throw 'Use 64-bit Windows PowerShell or the provided .cmd launcher.' }
    if ($Check -and $RestoreBackup) { throw 'Use either -Check or -RestoreBackup, not both.' }
    $taskRoot = [IO.Path]::GetFullPath($UserDataDirectory).TrimEnd('\')
    if (-not (Test-Path -LiteralPath (Join-Path $taskRoot 'Local State') -PathType Leaf)) { throw ('Local State not found: ' + $taskRoot) }
    if (-not $Check) { Assert-TaskChromeClosed }

    $taskSource = @'
using System;
using System.Collections.Generic;
using System.IO;
using System.Runtime.InteropServices;
using System.Text;
using System.Text.RegularExpressions;

namespace ChromeCountryFix {
    public sealed class Result {
        public byte[] Bytes;
        public string[] Audit;
        public string[] Changes;
        public int Count { get { return Changes.Length; } }
    }
    public static class Engine {
        const int Limit = 50 * 1024 * 1024;
        static readonly UTF8Encoding Utf8 = new UTF8Encoding(false, true);
        [DllImport("kernel32.dll", CharSet=CharSet.Unicode, SetLastError=true)]
        static extern IntPtr LoadLibraryEx(string file, IntPtr reserved, uint flags);
        [DllImport("kernel32.dll", CharSet=CharSet.Ansi, ExactSpelling=true)]
        static extern IntPtr GetProcAddress(IntPtr module, string name);
        [DllImport("kernel32.dll")] static extern bool FreeLibrary(IntPtr module);
        [UnmanagedFunctionPointer(CallingConvention.Cdecl)]
        delegate ulong FrameSize([In] byte[] source, UIntPtr length);
        [UnmanagedFunctionPointer(CallingConvention.Cdecl)]
        delegate UIntPtr DecompressFn([Out] byte[] dest, UIntPtr capacity, [In] byte[] source, UIntPtr length);
        [UnmanagedFunctionPointer(CallingConvention.Cdecl)]
        delegate UIntPtr CompressFn([Out] byte[] dest, UIntPtr capacity, [In] byte[] source, UIntPtr length, int level);
        [UnmanagedFunctionPointer(CallingConvention.Cdecl)] delegate UIntPtr BoundFn(UIntPtr length);
        [UnmanagedFunctionPointer(CallingConvention.Cdecl)] delegate uint IsErrorFn(UIntPtr code);
        [UnmanagedFunctionPointer(CallingConvention.Cdecl)] delegate IntPtr ErrorNameFn(UIntPtr code);
        static IntPtr Module;
        static FrameSize Size;
        static DecompressFn Decomp;
        static CompressFn Comp;
        static BoundFn Bound;
        static IsErrorFn IsError;
        static ErrorNameFn ErrorName;
        static T Function<T>(string name) where T : class {
            IntPtr p = GetProcAddress(Module, name);
            if (p == IntPtr.Zero) throw new InvalidDataException("Missing Zstandard export: " + name);
            return Marshal.GetDelegateForFunctionPointer(p, typeof(T)) as T;
        }
        public static void Init(string library) {
            if (IntPtr.Size != 8) throw new PlatformNotSupportedException("Use 64-bit Windows PowerShell.");
            Module = LoadLibraryEx(Path.GetFullPath(library), IntPtr.Zero, 0x800);
            if (Module == IntPtr.Zero) throw new System.ComponentModel.Win32Exception(Marshal.GetLastWin32Error());
            Size=Function<FrameSize>("ZSTD_getFrameContentSize");
            Decomp=Function<DecompressFn>("ZSTD_decompress");
            Comp=Function<CompressFn>("ZSTD_compress");
            Bound=Function<BoundFn>("ZSTD_compressBound");
            IsError=Function<IsErrorFn>("ZSTD_isError");
            ErrorName=Function<ErrorNameFn>("ZSTD_getErrorName");
        }
        public static void Close() { if (Module != IntPtr.Zero) { FreeLibrary(Module); Module=IntPtr.Zero; } }
        static UIntPtr U(int n) { return new UIntPtr((uint)n); }
        static int CheckedSize(UIntPtr code) {
            if (IsError(code) != 0) throw new InvalidDataException(Marshal.PtrToStringAnsi(ErrorName(code)));
            ulong n=code.ToUInt64();
            if (n > Limit + 1024 * 1024) throw new InvalidDataException("Zstandard output exceeds size limit.");
            return (int)n;
        }
        public static byte[] Decode(byte[] raw) {
            if (raw.Length < 4 || raw.Length > Limit || raw[0]!=0x28 || raw[1]!=0xb5 || raw[2]!=0x2f || raw[3]!=0xfd)
                throw new InvalidDataException("Expected a Zstandard V2 seed file; format is unsupported.");
            ulong length=Size(raw,U(raw.Length));
            if (length==0 || length > Limit) throw new InvalidDataException("Invalid or oversized Zstandard frame.");
            byte[] plain=new byte[(int)length];
            if (CheckedSize(Decomp(plain,U(plain.Length),raw,U(raw.Length)))!=plain.Length)
                throw new InvalidDataException("Unexpected decompressed size.");
            return plain;
        }
        public static byte[] Encode(byte[] plain) {
            byte[] buffer=new byte[CheckedSize(Bound(U(plain.Length)))];
            int n=CheckedSize(Comp(buffer,U(buffer.Length),plain,U(plain.Length),2));
            Array.Resize(ref buffer,n);
            if (!Equal(Decode(buffer),plain)) throw new InvalidDataException("Compression round-trip failed.");
            return buffer;
        }
        public static bool Equal(byte[] a,byte[] b) {
            if (a.Length!=b.Length) return false;
            for(int i=0;i<a.Length;i++) if(a[i]!=b[i]) return false;
            return true;
        }
        sealed class Field { public int Number, Wire, Offset, Length; }
        static ulong Varint(byte[] b,ref int pos) {
            ulong n=0;
            for(int i=0;i<10;i++) {
                if(pos>=b.Length) throw new InvalidDataException("Truncated protobuf varint.");
                byte x=b[pos++];
                if(i==9 && x>1) throw new InvalidDataException("Overflowing protobuf varint.");
                n|=(ulong)(x & 127) << (7*i);
                if((x & 128)==0) return n;
            }
            throw new InvalidDataException("Invalid protobuf varint.");
        }
        static List<Field> Fields(byte[] b) {
            var list=new List<Field>(); int p=0;
            while(p<b.Length) {
                ulong tag=Varint(b,ref p);
                if((tag>>3)==0 || (tag>>3)>536870911) throw new InvalidDataException("Invalid protobuf field tag.");
                var f=new Field {Number=(int)(tag>>3),Wire=(int)(tag&7)};
                if(f.Wire==0) { f.Offset=p; Varint(b,ref p); f.Length=p-f.Offset; }
                else {
                    ulong length;
                    if(f.Wire==2) length=Varint(b,ref p);
                    else if(f.Wire==1) length=8;
                    else if(f.Wire==5) length=4;
                    else throw new InvalidDataException("Unsupported protobuf wire type.");
                    if(length>(ulong)(b.Length-p)) throw new InvalidDataException("Truncated protobuf field.");
                    f.Offset=p; f.Length=(int)length; p+=f.Length;
                }
                list.Add(f);
            }
            return list;
        }
        public static Result Seed(byte[] raw) {
            byte[] plain=Decode(raw); var fields=Fields(plain);
            var audit=new List<string>(); var changes=new List<string>(); var seen=new HashSet<int>();
            bool hasData=false;
            foreach(var f in fields) {
                if(f.Number==1 || f.Number==2 || f.Number==6 || f.Number==7) {
                    if(!seen.Add(f.Number) || f.Wire!=2) throw new InvalidDataException("Unexpected StoredSeedInfo schema.");
                }
                if(f.Number==1) hasData=true;
                if(f.Number!=6 && f.Number!=7) continue;
                string name=f.Number==6 ? "session_country_code" : "permanent_country_code";
                string value=Utf8.GetString(plain,f.Offset,f.Length);
                if(value.Length!=0 && !Regex.IsMatch(value,"^[A-Za-z]{2}$")) throw new InvalidDataException("Invalid country field: " + name);
                audit.Add(name + "=" + value);
                if(String.Equals(value,"cn",StringComparison.OrdinalIgnoreCase)) {
                    plain[f.Offset]=(byte)'u'; plain[f.Offset+1]=(byte)'s';
                    changes.Add(name + ": " + value + " -> us");
                }
            }
            if(!hasData) throw new InvalidDataException("StoredSeedInfo data field is missing.");
            return new Result {Bytes=changes.Count>0 ? Encode(plain) : raw, Audit=audit.ToArray(), Changes=changes.ToArray()};
        }
        sealed class Node {
            public char Kind; public int Start,End; public string Value;
            public List<Node> Items; public Dictionary<string,Node> Members;
        }
        sealed class Json {
            readonly string S; int P;
            public Json(string s) {S=s; if(s.Length>0 && s[0]=='\ufeff') P=1;}
            void Space() {while(P<S.Length && (S[P]==' ' || S[P]=='\t' || S[P]=='\r' || S[P]=='\n')) P++;}
            void Expect(char c) {Space(); if(P>=S.Length || S[P++]!=c) throw new InvalidDataException("Invalid JSON punctuation.");}
            Node String() {
                var n=new Node {Kind='s',Start=P}; Expect('"'); var value=new StringBuilder();
                while(P<S.Length) {
                    char c=S[P++];
                    if(c=='"') {n.End=P; n.Value=value.ToString(); return n;}
                    if(c<32) throw new InvalidDataException("Invalid JSON string.");
                    if(c!='\\') {value.Append(c); continue;}
                    if(P>=S.Length) throw new InvalidDataException("Truncated JSON escape.");
                    c=S[P++];
                    switch(c) {
                        case '"': case '\\': case '/': value.Append(c); break;
                        case 'b': value.Append('\b'); break; case 'f': value.Append('\f'); break;
                        case 'n': value.Append('\n'); break; case 'r': value.Append('\r'); break; case 't': value.Append('\t'); break;
                        case 'u':
                            if(P+4>S.Length) throw new InvalidDataException("Truncated Unicode escape.");
                            ushort u;
                            if(!UInt16.TryParse(S.Substring(P,4),System.Globalization.NumberStyles.HexNumber,System.Globalization.CultureInfo.InvariantCulture,out u))
                                throw new InvalidDataException("Invalid Unicode escape.");
                            value.Append((char)u); P+=4; break;
                        default: throw new InvalidDataException("Invalid JSON escape.");
                    }
                }
                throw new InvalidDataException("Unterminated JSON string.");
            }
            Node Value(int depth) {
                if(depth>256) throw new InvalidDataException("JSON nesting exceeds limit.");
                Space(); if(P>=S.Length) throw new InvalidDataException("Truncated JSON value.");
                if(S[P]=='"') return String();
                var n=new Node {Kind=S[P],Start=P};
                if(S[P]=='{' || S[P]=='[') {
                    bool obj=S[P++]=='{'; char end=obj ? '}' : ']';
                    if(obj) n.Members=new Dictionary<string,Node>(); else n.Items=new List<Node>();
                    Space();
                    if(P<S.Length && S[P]==end) {P++; n.End=P; return n;}
                    while(true) {
                        if(obj) {
                            Space(); if(P>=S.Length || S[P]!='"') throw new InvalidDataException("Invalid JSON key.");
                            string key=String().Value; Expect(':');
                            if(n.Members.ContainsKey(key)) throw new InvalidDataException("Duplicate JSON key.");
                            n.Members.Add(key,Value(depth+1));
                        } else n.Items.Add(Value(depth+1));
                        Space(); if(P>=S.Length) throw new InvalidDataException("Unterminated JSON container.");
                        if(S[P]==end) {P++; break;}
                        Expect(',');
                    }
                } else {
                    int begin=P;
                    while(P<S.Length && S[P]!=',' && S[P]!='}' && S[P]!=']' && S[P]!=' ' && S[P]!='\t' && S[P]!='\r' && S[P]!='\n') P++;
                    string literal=S.Substring(begin,P-begin);
                    if(literal!="true" && literal!="false" && literal!="null" && !Regex.IsMatch(literal,"^-?(0|[1-9][0-9]*)(\\.[0-9]+)?([eE][+-]?[0-9]+)?$"))
                        throw new InvalidDataException("Invalid JSON literal.");
                    n.Value=literal;
                }
                n.End=P; return n;
            }
            public Node Parse() {Node n=Value(0); Space(); if(P!=S.Length) throw new InvalidDataException("Trailing JSON content."); return n;}
        }
        public static Result LocalState(byte[] raw) {
            if(raw.Length>16*1024*1024) throw new InvalidDataException("Local State exceeds size limit.");
            string text=Utf8.GetString(raw); Node root=new Json(text).Parse();
            if(root.Kind!='{') throw new InvalidDataException("Local State must be a JSON object.");
            string[] keys={"variations_country","variations_permanent_consistency_country","variations_safe_seed_session_consistency_country","variations_safe_seed_permanent_consistency_country"};
            var audit=new List<string>(); var changes=new List<string>(); var patches=new List<Node>();
            foreach(string key in keys) {
                Node n;
                if(!root.Members.TryGetValue(key,out n)) {audit.Add(key + "=<absent>"); continue;}
                if(key=="variations_permanent_consistency_country") {
                    if(n.Kind!='[' || n.Items.Count!=2 || n.Items[0].Kind!='s') throw new InvalidDataException("Unexpected permanent-country array.");
                    n=n.Items[1];
                }
                if(n.Kind!='s' || (n.Value.Length!=0 && !Regex.IsMatch(n.Value,"^[A-Za-z]{2}$")))
                    throw new InvalidDataException("Invalid Local State country field: " + key);
                audit.Add(key + "=" + n.Value);
                if(String.Equals(n.Value,"cn",StringComparison.OrdinalIgnoreCase)) {patches.Add(n); changes.Add(key + ": " + n.Value + " -> us");}
            }
            patches.Sort(delegate(Node a,Node b) {return b.Start.CompareTo(a.Start);});
            foreach(Node n in patches) text=text.Substring(0,n.Start) + "\"us\"" + text.Substring(n.End);
            if(patches.Count>0) new Json(text).Parse();
            return new Result {Bytes=patches.Count>0 ? Utf8.GetBytes(text) : raw, Audit=audit.ToArray(), Changes=changes.ToArray()};
        }
    }
}

