    try { $taskGzip.CopyTo($taskUnpacked); $taskLibraryBytes = $taskUnpacked.ToArray() }
    finally { $taskGzip.Dispose(); $taskUnpacked.Dispose(); $taskPacked.Dispose() }
    if ((Get-TaskHash $taskLibraryBytes) -ne $taskLibraryHash) { throw 'Embedded Zstandard library integrity check failed.' }
    $taskRuntimeDirectory = Join-Path ([IO.Path]::GetTempPath()) ('ChromeCountryFix-' + [Guid]::NewGuid().ToString('N'))
    [void][IO.Directory]::CreateDirectory($taskRuntimeDirectory)
    $taskLibraryPath = Join-Path $taskRuntimeDirectory 'zstd.dll'
    [IO.File]::WriteAllBytes($taskLibraryPath, $taskLibraryBytes)
    [ChromeCountryFix.Engine]::Init($taskLibraryPath)

    $taskNames = @('Local State', 'VariationsSeedV2', 'VariationsSafeSeedV2')
    $taskRestoreManifest = $null
    if ($RestoreBackup) {
        $taskRestoreDirectory = [IO.Path]::GetFullPath($RestoreBackup)
        $taskRestoreManifest = Get-Content -LiteralPath (Join-Path $taskRestoreDirectory 'manifest.json') -Raw | ConvertFrom-Json
        if ($taskRestoreManifest.FormatVersion -ne 1 -or -not [String]::Equals([IO.Path]::GetFullPath($taskRestoreManifest.UserDataDirectory).TrimEnd('\'), $taskRoot, [StringComparison]::OrdinalIgnoreCase)) {
            throw 'Backup does not belong to this User Data directory.'
        }
        $taskNames = @($taskRestoreManifest.Files | ForEach-Object { $_.Name })
        if ($taskNames.Count -eq 0 -or @($taskNames | Select-Object -Unique).Count -ne $taskNames.Count) { throw 'Invalid backup file list.' }
        foreach ($taskName in $taskNames) {
            if ($taskName -notin @('Local State', 'VariationsSeedV2', 'VariationsSafeSeedV2')) { throw 'Unsupported filename in backup.' }
        }
    }

    foreach ($taskName in $taskNames) {
        $taskPath = Join-Path $taskRoot $taskName
        if (-not (Test-Path -LiteralPath $taskPath -PathType Leaf)) {
            if ($RestoreBackup) { throw ('Restore target is missing: ' + $taskName) }
            Write-Host ('SKIP ' + $taskName + ': file absent.')
            continue
        }
        if ((Get-Item -LiteralPath $taskPath).Attributes -band [IO.FileAttributes]::ReparsePoint) { throw ('Refusing reparse-point file: ' + $taskName) }
        $taskStream = $null
        if ($Check) { $taskOriginal = [IO.File]::ReadAllBytes($taskPath) }
        else {
            $taskStream = New-Object IO.FileStream($taskPath, [IO.FileMode]::Open, [IO.FileAccess]::ReadWrite, [IO.FileShare]::None)
            $taskStreams += $taskStream
            $taskOriginal = Read-TaskStream $taskStream
        }
        if ($RestoreBackup) {
            $taskNext = [IO.File]::ReadAllBytes((Join-Path $taskRestoreDirectory $taskName))
            $taskSavedRecord = $taskRestoreManifest.Files | Where-Object { $_.Name -eq $taskName }
            if ((Get-TaskHash $taskNext) -ne $taskSavedRecord.BeforeSHA256) { throw ('Backup hash mismatch: ' + $taskName) }
            $taskCount = [int](-not [ChromeCountryFix.Engine]::Equal($taskOriginal, $taskNext))
            $taskAudit = @('restore exact backup bytes')
            $taskChanges = @('restore from ' + $taskRestoreDirectory)
        } else {
            $taskPlan = if ($taskName -eq 'Local State') { [ChromeCountryFix.Engine]::LocalState($taskOriginal) } else { [ChromeCountryFix.Engine]::Seed($taskOriginal) }
            $taskNext = $taskPlan.Bytes
            $taskCount = $taskPlan.Count
            $taskAudit = $taskPlan.Audit
            $taskChanges = $taskPlan.Changes
        }
        Write-Host ('[' + $taskName + ']')
        foreach ($taskLine in $taskAudit) { Write-Host ('  ' + $taskLine) }
        foreach ($taskLine in $taskChanges) { Write-Host ('  CHANGE ' + $taskLine) }
        $taskEntries += [PSCustomObject]@{ Name=$taskName; Path=$taskPath; Stream=$taskStream; Original=$taskOriginal; Next=$taskNext; Count=$taskCount }
    }
    if ($Check) {
        $taskTotal = ($taskEntries | Measure-Object -Property Count -Sum).Sum
        Write-Host ('CHECK ONLY: ' + $taskTotal + ' country value(s) would change. No Chrome file was written.')
        $taskFinished = $true
    } elseif (@($taskEntries | Where-Object { $_.Count -gt 0 }).Count -eq 0) {
        Write-Host 'No changes needed. Existing files were left byte-for-byte unchanged.'
        $taskFinished = $true
    } else {
        Assert-TaskChromeClosed
        $taskBackupRoot = [IO.Path]::GetFullPath($BackupDirectory)
        [void][IO.Directory]::CreateDirectory($taskBackupRoot)
        $taskBackupPath = Join-Path $taskBackupRoot ((Get-Date -Format 'yyyyMMdd-HHmmss-fff') + '-' + [Guid]::NewGuid().ToString('N').Substring(0,8))
        [void][IO.Directory]::CreateDirectory($taskBackupPath)
        $taskBackupRecords = @()
        foreach ($taskEntry in $taskEntries) {
            $taskBackupFile = Join-Path $taskBackupPath $taskEntry.Name
            [IO.File]::WriteAllBytes($taskBackupFile, $taskEntry.Original)
            $taskBeforeHash = Get-TaskHash $taskEntry.Original
            if ((Get-TaskHash ([IO.File]::ReadAllBytes($taskBackupFile))) -ne $taskBeforeHash) { throw 'Backup verification failed.' }
            $taskBackupRecords += [PSCustomObject]@{ Name=$taskEntry.Name; BeforeSHA256=$taskBeforeHash; AfterSHA256=(Get-TaskHash $taskEntry.Next); Changed=($taskEntry.Count -gt 0) }
        }
        $taskManifest = [ordered]@{ FormatVersion=1; UserDataDirectory=$taskRoot; CreatedUTC=[DateTime]::UtcNow.ToString('o'); Operation=$(if ($RestoreBackup) {'restore'} else {'cn-to-us'}); Files=$taskBackupRecords }
        $taskManifestJson = $taskManifest | ConvertTo-Json -Depth 5
        [IO.File]::WriteAllText((Join-Path $taskBackupPath 'manifest.json'), $taskManifestJson, (New-Object Text.UTF8Encoding($false)))
        foreach ($taskEntry in $taskEntries) {
            if ($taskEntry.Count -eq 0) { continue }
            $taskWroteFiles = $true
            Write-TaskStream $taskEntry.Stream $taskEntry.Next
            $taskReadBack = Read-TaskStream $taskEntry.Stream
            if (-not [ChromeCountryFix.Engine]::Equal($taskReadBack, $taskEntry.Next)) { throw ('Read-back failed: ' + $taskEntry.Name) }
            if (-not $RestoreBackup) {
                $taskVerified = if ($taskEntry.Name -eq 'Local State') { [ChromeCountryFix.Engine]::LocalState($taskReadBack) } else { [ChromeCountryFix.Engine]::Seed($taskReadBack) }
                if ($taskVerified.Count -ne 0) { throw ('Country verification failed: ' + $taskEntry.Name) }
            }
        }
        $taskFinished = $true
        Write-Host 'SUCCESS: all changed files passed read-back verification.' -ForegroundColor Green
        Write-Host ('Backup: ' + $taskBackupPath)
    }
} catch {
    Write-Host ('ERROR: ' + $_.Exception.Message) -ForegroundColor Red
    if ($taskBackupPath) { Write-Host ('Backup: ' + $taskBackupPath) }
    if ($taskWroteFiles -and -not $taskFinished) {
        foreach ($taskEntry in $taskEntries) {
            try { Write-TaskStream $taskEntry.Stream $taskEntry.Original; Write-Host ('Rolled back: ' + $taskEntry.Name) }
            catch { Write-Host ('Rollback failed for ' + $taskEntry.Name + '; restore from the saved backup.') -ForegroundColor Red }
        }
    }
    exit 1
} finally {
    foreach ($taskStream in $taskStreams) { $taskStream.Dispose() }
    if ('ChromeCountryFix.Engine' -as [type]) { [ChromeCountryFix.Engine]::Close() }
    if ($taskRuntimeDirectory -and [IO.Directory]::Exists($taskRuntimeDirectory)) {
        try {
            [IO.File]::Delete((Join-Path $taskRuntimeDirectory 'zstd.dll'))
            [IO.Directory]::Delete($taskRuntimeDirectory, $false)
        } catch { Write-Host ('Temporary runtime directory: ' + $taskRuntimeDirectory) }
    }
}

